mapper.select:
SELECT tenant_id, owner_id, key_hash, request_fingerprint, operation, dataset_id,
    revision, definition_digest, created_at FROM knowledge_evaluation_command
WHERE  AND key_hash = #{key}

SELECT dataset_id, name, purpose, current_revision AS revision, question_count, created_at, updated_at
FROM knowledge_evaluation_dataset WHERE 
AND purpose = #{purpose}
AND dataset_id > #{after}
ORDER BY dataset_id LIMIT #{limit}

SELECT dataset_id, name, purpose, revision, question_count, definition_digest, created_at
FROM knowledge_evaluation_revision WHERE  AND dataset_id = #{id}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{limit}

mapper.update:
UPDATE knowledge_evaluation_dataset SET name = #{row.name}, purpose = #{row.purpose},
    current_revision = #{row.revision}, question_count = #{row.questionCount}, updated_at = #{row.updatedAt}
WHERE tenant_id = #{row.tenantId} AND owner_id = #{row.ownerId}
    AND dataset_id = #{row.datasetId} AND current_revision = #{expected}

