SELECT document_id FROM knowledge_document WHERE  AND document_id IN
#{id}
ORDER BY document_id FOR SHARE

 AND c.chunk_id IN
#{id}
ORDER BY c.document_id, c.document_version, c.chunk_id

 AND c.document_id = #{documentId} AND c.document_version = #{version}
AND c.chunk_id > #{after}
ORDER BY c.chunk_id LIMIT #{limit}
